package main

import (
	"fmt"
)

func main() {
	var A int64
	fmt.Scan(&A)

	if A == 1 {
		fmt.Println(1)
		return
	}

	// Generate all divisors of A
	divisors := make([]int64, 0)
	for i := int64(1); i*i <= A; i++ {
		if A%i == 0 {
			divisors = append(divisors, i)
			if i != A/i {
				divisors = append(divisors, A/i)
			}
		}
	}

	// Map to store valid candidates: maps d-1 -> d where d is a divisor of A
	// and d-1 is a prime power
	candidates := make(map[int64]int64)

	for _, d := range divisors {
		if d <= 2 {
			continue // d-1 must be >= 2 (prime power)
		}
		m := d - 1
		if isPrimePower(m) {
			candidates[m] = d
		}
	}

	// Extract candidate values (the divisors d)
	candList := make([]int64, 0, len(candidates))
	for _, d := range candidates {
		candList = append(candList, d)
	}

	// DP to count subsets of candidates whose product is A
	// Since |candidates| is small (<= ~100 for A<=1e12), use map
	dp := make(map[int64]int64)
	dp[1] = 1

	for _, c := range candList {
		newDp := make(map[int64]int64)
		for prod, count := range dp {
			// Not taking c
			newDp[prod] += count
			// Taking c
			if A%prod == 0 && (A/prod)%c == 0 {
				newProd := prod * c
				newDp[newProd] += count
			}
		}
		dp = newDp
	}

	fmt.Println(dp[A])
}

func isPrimePower(n int64) bool {
	if n < 2 {
		return false
	}
	// Find smallest prime factor
	p := int64(0)
	for i := int64(2); i*i <= n; i++ {
		if n%i == 0 {
			p = i
			break
		}
	}
	if p == 0 {
		// n is prime
		return true
	}
	// Check if n is a power of p
	for n%p == 0 {
		n /= p
	}
	return n == 1
}
